const TAB_DEFAULT_OPTION = {
  hair: "haircuts",
  skin: "skinCare",
  body: "bodyMassage",
};

const Switching = () => {
  const [activeTab, setActiveTab] = useState("hair");
  const [activeOption, setActiveOption] = useState("haircuts");

  const handleTabClick = (tab: keyof typeof tabContent) => {
    setActiveTab(tab);
    setActiveOption(TAB_DEFAULT_OPTION[tab]);
  };

  const currentContent = tabContent[activeTab][activeOption];

  return (
    <section className={styles.switchingContainer} aria-label="Beauty Services">
      <nav className={styles.tabs} aria-label="Service categories">
        {Object.keys(tabContent).map((tab) => (
          <button
            key={tab}
            onClick={() => handleTabClick(tab as keyof typeof tabContent)}
            className={activeTab === tab ? styles.active : ""}
            aria-pressed={activeTab === tab}
            aria-label={`${tab.charAt(0).toUpperCase() + tab.slice(1)} services`}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </nav>

      <div className={styles.contentContainer}>
        <nav className={styles.leftOptions} aria-label="Service options">
          {Object.keys(tabContent[activeTab]).map((option) => (
            <button
              key={option}
              onClick={() => setActiveOption(option)}
              className={activeOption === option ? styles.active : ""}
              aria-pressed={activeOption === option}
            >
              {tabContent[activeTab][option].title}
            </button>
          ))}
        </nav>

        <article className={styles.rightContent}>
          <div className={styles.tabImage}>
            <Image
              src={currentContent.imgSrc}
              alt={`${currentContent.title} at Lovely Looks Beauty Salon`}
              width={400}
              height={328}
              className={styles.fixedImage}
              loading="lazy"
              sizes="(max-width: 468px) 100vw, (max-width: 768px) 100vw, 40vw"
              unoptimized
            />
          </div>
          <div className={styles.tabDescription}>
            <h3>{currentContent.title}</h3>
            <p>{currentContent.description}</p>
            <button className={styles.enquiryBtn}>
              Book a Service Today
            </button>
          </div>
        </article>
      </div>
    </section>
  );
};

export default Switching;